class Solution {
public:
    int countGoodSubsequences(std::string s) {
        long long MOD = 1e9 + 7;
        std::vector<int> counts(26, 0);
        for (char ch : s) counts[ch - 'a']++;
        int max_c = *std::max_element(counts.begin(), counts.end());

        std::vector<long long> fact(max_c + 1, 1), inv(max_c + 1, 1);
        auto modpow = [&](long long base, long long exp) {
            long long res = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp % 2 == 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp /= 2;
            }
            return res;
        };
        for (int i = 1; i <= max_c; ++i) fact[i] = (fact[i - 1] * i) % MOD;
        inv[max_c] = modpow(fact[max_c], MOD - 2);
        for (int i = max_c - 1; i >= 0; --i) inv[i] = (inv[i + 1] * (i + 1)) % MOD;

        auto nCr = [&](int n, int r) -> long long {
            if (r < 0 || r > n) return 0;
            return fact[n] * inv[r] % MOD * inv[n - r] % MOD;
        };

        long long ans = 0;
        for (int f = 1; f <= max_c; ++f) {
            long long ways = 1;
            for (int c : counts) {
                if (c >= f) ways = (ways * (1 + nCr(c, f))) % MOD;
            }
            ans = (ans + ways - 1 + MOD) % MOD;
        }
        return ans;
    }
};

class Solution {
    private long MOD = 1_000_000_007L;
    public int countGoodSubsequences(String s) {
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) counts[s.charAt(i) - 'a']++;
        int maxC = 0;
        for (int c : counts) maxC = Math.max(maxC, c);

        long[] fact = new long[maxC + 1];
        long[] inv = new long[maxC + 1];
        fact[0] = 1;
        for (int i = 1; i <= maxC; i++) fact[i] = (fact[i - 1] * i) % MOD;
        inv[maxC] = modPow(fact[maxC], MOD - 2);
        for (int i = maxC - 1; i >= 0; i--) inv[i] = (inv[i + 1] * (i + 1)) % MOD;

        long ans = 0;
        for (int f = 1; f <= maxC; f++) {
            long ways = 1;
            for (int c : counts) {
                if (c >= f) {
                    long comb = fact[c] * inv[f] % MOD * inv[c - f] % MOD;
                    ways = (ways * (1 + comb)) % MOD;
                }
            }
            ans = (ans + ways - 1 + MOD) % MOD;
        }
        return (int)ans;
    }
    private long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

var countGoodSubsequences = function(s) {
    const MOD = 1000000007n;
    const counts = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) counts[s.charCodeAt(i) - 97]++;
    let maxC = 0;
    for (const c of counts) if (c > maxC) maxC = c;

    const fact = new Array(maxC + 1);
    fact[0] = 1n;
    for (let i = 1; i <= maxC; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;

    const modPow = (base, exp) => {
        let res = 1n;
        base %= MOD;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    };

    const inv = new Array(maxC + 1);
    inv[maxC] = modPow(fact[maxC], MOD - 2n);
    for (let i = maxC - 1; i >= 0; i--) inv[i] = (inv[i + 1] * BigInt(i + 1)) % MOD;

    const nCr = (n, r) => {
        if (r < 0 || r > n) return 0n;
        return (fact[n] * inv[r] % MOD) * inv[n - r] % MOD;
    };

    let ans = 0n;
    for (let f = 1; f <= maxC; f++) {
        let ways = 1n;
        for (const c of counts) {
            if (c >= f) ways = (ways * (1n + nCr(c, f))) % MOD;
        }
        ans = (ans + ways - 1n + MOD) % MOD;
    }
    return Number(ans);
};
